:root { color: rgb(23, 33, 27); background: rgb(236, 238, 232); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-synthesis: none; text-rendering: optimizelegibility; }* { box-sizing: border-box; }html { min-width: 320px; min-height: 100%; background: rgb(236, 238, 232); }body { min-width: 320px; min-height: 100vh; margin: 0px; }button, a { font: inherit; }button { color: inherit; }button:focus-visible, a:focus-visible { outline: rgba(110, 75, 163, 0.35) solid 3px; outline-offset: 3px; }[hidden] { display: none !important; }.app-shell { display: grid; grid-template-columns: 220px minmax(0px, 1fr); min-height: 100vh; }.sidebar { position: sticky; top: 0px; display: flex; flex-direction: column; height: 100vh; padding: 30px 22px 22px; border-right: 1px solid rgba(31, 42, 34, 0.09); background: rgba(247, 248, 243, 0.88); }.brand { display: flex; align-items: center; gap: 11px; color: rgb(25, 36, 28); font-size: 19px; font-weight: 780; letter-spacing: -0.04em; text-decoration: none; }.brand-mark { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; color: rgb(247, 247, 241); background: rgb(39, 54, 43); font-family: Georgia, serif; font-size: 18px; font-style: italic; }.nav { display: grid; gap: 6px; margin-top: 54px; }.nav-item { display: flex; align-items: center; gap: 12px; padding: 11px 12px; border-radius: 11px; color: rgb(124, 133, 126); font-size: 13px; font-weight: 640; text-decoration: none; transition: 150ms; }.nav-item span { width: 18px; color: rgb(154, 161, 155); font-size: 17px; text-align: center; }.nav-item:hover { color: rgb(38, 50, 41); background: rgba(38, 50, 41, 0.05); }.nav-item.active { color: rgb(32, 43, 35); background: rgb(225, 231, 221); }.sidebar-bottom { margin-top: auto; }.workspace-card { display: grid; grid-template-columns: 34px 1fr auto; align-items: center; gap: 9px; padding: 10px; border: 1px solid rgba(34, 45, 37, 0.08); border-radius: 13px; background: rgb(255, 255, 255); }.workspace-avatar { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; color: rgb(255, 255, 255); background: rgb(110, 75, 163); font-size: 12px; font-weight: 800; }.workspace-card strong, .workspace-card small { display: block; }.workspace-card strong { font-size: 10px; }.workspace-card small { margin-top: 2px; color: rgb(147, 154, 148); font-size: 8px; }.workspace-more { color: rgb(154, 161, 155); font-size: 10px; letter-spacing: 0.06em; }.main-content { width: min(1180px, 100%); margin: 0px auto; padding: 48px clamp(28px, 5vw, 72px) 80px; }.topbar { display: flex; align-items: center; justify-content: space-between; margin-bottom: 40px; }.eyebrow, .card-kicker { color: rgb(141, 151, 143); font-size: 9px; font-weight: 800; letter-spacing: 0.16em; }.topbar h1 { margin: 8px 0px 0px; color: rgb(28, 41, 31); font-family: Georgia, "Times New Roman", serif; font-size: clamp(30px, 4vw, 47px); font-weight: 400; letter-spacing: -0.045em; }.top-actions { display: flex; gap: 10px; }.icon-action, .avatar-button { display: grid; place-items: center; width: 40px; height: 40px; border: 1px solid rgba(31, 42, 34, 0.09); border-radius: 50%; background: rgba(255, 255, 255, 0.75); cursor: pointer; }.icon-action { font-size: 19px; }.avatar-button { color: rgb(247, 247, 241); background: rgb(38, 55, 43); font-size: 10px; font-weight: 800; }.hero-grid { display: grid; grid-template-columns: minmax(0px, 1.75fr) minmax(280px, 0.75fr); gap: 18px; }.focus-card, .demo-guide, .activity-card, .trace-card { border: 1px solid rgba(31, 42, 34, 0.08); border-radius: 24px; }.focus-card { position: relative; min-height: 365px; overflow: hidden; color: rgb(245, 244, 237); background: rgb(38, 55, 43); box-shadow: rgba(31, 48, 37, 0.14) 0px 22px 55px; }.focus-glow { position: absolute; inset: auto auto -55% -12%; width: 70%; aspect-ratio: 1 / 1; border-radius: 50%; background: rgba(124, 160, 104, 0.22); filter: blur(50px); }.focus-copy { position: relative; z-index: 2; width: 58%; padding: 43px; }.focus-card .card-kicker { color: rgb(174, 187, 173); }.focus-card h2 { margin: 18px 0px 14px; font-family: Georgia, "Times New Roman", serif; font-size: clamp(31px, 4vw, 49px); font-weight: 400; line-height: 0.98; letter-spacing: -0.045em; }.focus-card p { max-width: 330px; margin: 0px; color: rgb(185, 195, 186); font-size: 12px; line-height: 1.65; }.primary-action { display: inline-flex; align-items: center; gap: 28px; margin-top: 28px; padding: 12px 15px 12px 17px; border: 0px; border-radius: 999px; color: rgb(39, 54, 43); background: rgb(240, 233, 214); font-size: 11px; font-weight: 760; cursor: pointer; transition: transform 150ms, background 150ms; }.primary-action:hover { transform: translateY(-2px); background: rgb(255, 248, 230); }.primary-action span { font-size: 16px; }.orbital-art { position: absolute; top: 28px; right: 22px; width: 44%; height: calc(100% - 56px); }.planet { position: absolute; top: 50%; left: 50%; width: 118px; height: 118px; transform: translate(-50%, -50%); border: 1px solid rgba(255, 255, 255, 0.14); border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgb(189, 207, 170), rgb(109, 141, 102) 52%, rgb(50, 78, 56) 100%); box-shadow: rgba(0, 0, 0, 0.2) -18px -15px 30px inset, rgba(0, 0, 0, 0.22) 0px 25px 45px; }.orbit { position: absolute; top: 50%; left: 50%; border: 1px solid rgba(222, 232, 211, 0.25); border-radius: 50%; transform: translate(-50%, -50%) rotate(-28deg); }.orbit-one { width: 224px; height: 104px; }.orbit-two { width: 285px; height: 148px; transform: translate(-50%, -50%) rotate(34deg); }.star { position: absolute; color: rgb(230, 237, 220); }.star-one { top: 18%; right: 14%; font-size: 18px; }.star-two { bottom: 17%; left: 8%; font-size: 34px; }.demo-guide { padding: 30px; background: rgb(247, 246, 240); }.card-kicker.dark { color: rgb(138, 147, 140); }.demo-guide h3, .section-heading h3 { margin: 11px 0px 0px; font-family: Georgia, "Times New Roman", serif; font-size: 24px; font-weight: 400; letter-spacing: -0.03em; }.demo-guide ol { display: grid; gap: 14px; margin: 26px 0px 24px; padding: 0px; list-style: none; }.demo-guide li { display: flex; align-items: center; gap: 10px; color: rgb(105, 115, 107); font-size: 11px; line-height: 1.4; }.demo-guide li span { display: grid; flex: 0 0 auto; place-items: center; width: 24px; height: 24px; border: 1px solid rgba(38, 55, 43, 0.12); border-radius: 50%; color: rgb(62, 76, 66); background: rgb(255, 255, 255); font-size: 9px; font-weight: 800; }.shortcut-hint { display: flex; align-items: center; gap: 4px; padding-top: 18px; border-top: 1px solid rgba(31, 42, 34, 0.08); color: rgb(160, 167, 161); font-size: 8px; }.shortcut-hint kbd { padding: 4px 6px; border-width: 1px 1px 2px; border-style: solid; border-color: rgba(31, 42, 34, 0.12); border-image: none; border-radius: 5px; color: rgb(75, 87, 78); background: rgb(255, 255, 255); font: 700 8px ui-monospace, monospace; }.shortcut-hint b { font-weight: 500; }.shortcut-hint span { margin-left: auto; }.content-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 18px; }.activity-card, .trace-card { min-height: 290px; padding: 28px; background: rgba(248, 249, 244, 0.8); }.section-heading { display: flex; align-items: flex-start; justify-content: space-between; }.section-heading h3 { font-size: 22px; }.text-button { border: 0px; color: rgb(124, 133, 126); background: none; font-size: 9px; font-weight: 700; cursor: pointer; }.activity-list { display: grid; margin-top: 23px; }.activity-row { display: grid; grid-template-columns: 9px 1fr auto; align-items: center; gap: 13px; padding: 14px 0px; border-top: 1px solid rgba(31, 42, 34, 0.07); }.activity-dot { width: 7px; height: 7px; border-radius: 50%; }.activity-dot.violet { background: rgb(141, 104, 189); }.activity-dot.blue { background: rgb(102, 147, 180); }.activity-dot.amber { background: rgb(198, 152, 89); }.activity-row strong, .activity-row small { display: block; }.activity-row strong { font-size: 11px; }.activity-row small { margin-top: 3px; color: rgb(152, 160, 152); font-size: 9px; }.activity-row time { color: rgb(164, 170, 165); font-size: 9px; }.live-pill { display: flex; align-items: center; gap: 5px; padding: 5px 8px; border-radius: 999px; color: rgb(113, 130, 118); background: rgb(230, 236, 228); font-size: 8px; font-weight: 800; text-transform: uppercase; }.live-pill i { width: 5px; height: 5px; border-radius: 50%; background: rgb(107, 143, 113); }.request-log { display: grid; margin-top: 23px; }.log-empty { display: grid; place-items: center; min-height: 155px; border: 1px dashed rgba(31, 42, 34, 0.13); border-radius: 15px; color: rgb(157, 164, 158); font-size: 10px; text-align: center; }.log-row { display: grid; grid-template-columns: 27px 1fr auto; align-items: center; gap: 11px; padding: 11px 0px; border-top: 1px solid rgba(31, 42, 34, 0.07); }.log-kind { display: grid; place-items: center; width: 25px; height: 25px; border-radius: 8px; color: rgb(255, 255, 255); background: rgb(116, 129, 120); font-size: 8px; font-weight: 900; }.log-kind.response { background: rgb(108, 145, 165); }.log-kind.user { background: rgb(169, 134, 89); }.log-kind.mutation { background: rgb(138, 104, 173); }.log-row strong, .log-row small { display: block; }.log-row strong { font: 600 9px ui-monospace, monospace; }.log-row small { margin-top: 3px; color: rgb(152, 160, 152); font-size: 8px; }.log-row time { color: rgb(161, 167, 162); font: 8px ui-monospace, monospace; }.modal-layer { position: fixed; inset: 0px; z-index: 1000; display: grid; place-items: center; padding: 22px; background: rgba(21, 31, 24, 0.58); backdrop-filter: blur(9px); }.sync-modal { position: relative; width: min(430px, 100%); padding: 42px; border: 1px solid rgba(255, 255, 255, 0.8); border-radius: 26px; background: rgb(250, 249, 244); box-shadow: rgba(17, 27, 20, 0.32) 0px 30px 90px; animation: 220ms ease-out 0s 1 normal none running modal-in; }.modal-close { position: absolute; top: 16px; right: 16px; display: grid; place-items: center; width: 32px; height: 32px; border: 1px solid rgba(31, 42, 34, 0.1); border-radius: 50%; color: rgb(126, 136, 128); background: rgb(255, 255, 255); font-size: 17px; cursor: pointer; }.sync-icon { position: relative; display: grid; place-items: center; width: 48px; height: 48px; margin-bottom: 25px; border-radius: 15px; background: rgb(228, 233, 223); }.sync-icon span { width: 20px; height: 20px; border-width: 2px; border-style: solid; border-color: transparent rgb(130, 145, 132) rgb(130, 145, 132); border-image: none; border-radius: 50%; animation: 900ms linear 0s infinite normal none running spin; }.sync-icon.success { background: rgb(223, 234, 221); }.sync-icon.success span { width: 18px; height: 10px; border-width: 0px 0px 2px 2px; border-style: none none solid solid; border-color: currentcolor currentcolor rgb(82, 114, 90) rgb(82, 114, 90); border-image: none; border-radius: 0px; transform: rotate(-45deg); animation: auto ease 0s 1 normal none running none; }.sync-modal h2 { margin: 11px 0px 10px; color: rgb(29, 42, 32); font-family: Georgia, "Times New Roman", serif; font-size: 29px; font-weight: 400; letter-spacing: -0.04em; }.sync-modal p { margin: 0px; color: rgb(126, 135, 128); font-size: 11px; line-height: 1.65; }.progress-track { height: 4px; margin: 28px 0px 22px; overflow: hidden; border-radius: 999px; background: rgb(227, 231, 223); }.progress-track i { display: block; width: 42%; height: 100%; border-radius: inherit; background: rgb(109, 128, 111); animation: 1.2s ease-in-out 0s infinite alternate none running progress; }.modal-primary { width: 100%; height: 42px; border: 0px; border-radius: 12px; color: rgb(246, 245, 239); background: rgb(41, 57, 45); font-size: 11px; font-weight: 750; cursor: pointer; }.modal-primary:disabled { color: rgb(157, 165, 158); background: rgb(228, 231, 225); cursor: not-allowed; }.bug-toast { position: fixed; left: 50%; bottom: 26px; z-index: 1100; display: flex; align-items: center; gap: 12px; min-width: 330px; padding: 13px 16px; border: 1px solid rgba(111, 74, 151, 0.25); border-radius: 14px; color: rgb(247, 244, 250); background: rgb(62, 46, 80); box-shadow: rgba(22, 14, 31, 0.3) 0px 18px 50px; transform: translateX(-50%); }.bug-toast > span { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; color: rgb(67, 44, 91); background: rgb(216, 195, 237); font-weight: 900; }.bug-toast strong, .bug-toast small { display: block; }.bug-toast strong { font-size: 10px; }.bug-toast small { margin-top: 3px; color: rgb(203, 188, 214); font-size: 8px; }@keyframes spin { 
  100% { transform: rotate(360deg); }
}@keyframes progress { 
  0% { transform: translateX(-20%); }
  100% { transform: translateX(170%); }
}@keyframes modal-in { 
  0% { opacity: 0; transform: translateY(10px) scale(0.98); }
}@media (max-width: 900px) {
  .app-shell { grid-template-columns: 74px minmax(0px, 1fr); }
  .sidebar { padding-inline: 13px; }
  .brand > span:last-child, .nav-item:not(.active) { font-size: 0px; }
  .nav-item { justify-content: center; }
  .nav-item span { font-size: 18px; }
  .workspace-card { display: grid; grid-template-columns: 1fr; }
  .workspace-card > div, .workspace-more { display: none; }
  .hero-grid { grid-template-columns: 1fr; }
  .demo-guide { min-height: 0px; }
}@media (max-width: 660px) {
  .app-shell { display: block; }
  .sidebar { display: none; }
  .main-content { padding: 28px 18px 90px; }
  .topbar { margin-bottom: 28px; }
  .topbar h1 { font-size: 32px; }
  .content-grid { grid-template-columns: 1fr; }
  .focus-card { min-height: 430px; }
  .focus-copy { width: 100%; padding: 34px; }
  .focus-card h2 { font-size: 38px; }
  .orbital-art { top: auto; right: 0px; bottom: -50px; width: 65%; height: 230px; opacity: 0.68; }
}
